input.new_string:
    /**
     * 判断点是否位于闭矩形内（含边界）。
     */
    public static boolean inRectangle(long x, long y,
                                      int xMin, int yMin, int xMax, int yMax) {
        return x >= xMin && x <= xMax && y >= yMin && y <= yMax;
    }

    /**
     * 判断一条二次贝塞尔曲线段（含全部 t∈[0,1] 的点）是否与轴对齐闭矩形相交。
     * 内部穿越、边界接触、单点相切均返回 true。
     *
     * <p>精确解析法，不做有限离散采样，也不以控制点包围盒相交直接判阻断：
     * B(t)=(1-t)^2*P0+2t(1-t)*P1+t^2*P2 的两个坐标均为整系数二次多项式，
     * 分别求坐标进入闭区间 [min,max] 的 t 区间，再求 x/y 两区间与 [0,1] 的交集；
     * 交集非空即存在真实曲线上的点位于矩形内或边界上。</p>
     *
     * @param seg 二次曲线段（P0/P1/P2 为整数坐标）
     */
    public static boolean quadraticHitsRectangle(CurveSegment seg,
                                                 int xMin, int yMin, int xMax, int yMax) {
        double[] tRange = {0.0d, 1.0d};
        return intervalForQuadratic(seg.p0().x(), seg.p1().x(), seg.p2().x(), xMin, xMax, tRange)
                && intervalForQuadratic(seg.p0().y(), seg.p1().y(), seg.p2().y(), yMin, yMax, tRange)
                && tRange[0] <= tRange[1];
    }

    /**
     * 判断有序二次曲线段组成的曲线（段间首尾端点相等）是否与闭矩形相交。
     */
    public static boolean curveHitsRectangle(List<CurveSegment> segments,
                                             int xMin, int yMin, int xMax, int yMax) {
        for (CurveSegment seg : segments) {
            if (quadraticHitsRectangle(seg, xMin, yMin, xMax, yMax)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 求整系数二次多项式 q(t)=a(1-t)^2+2bt(1-t)+ct^2 在 t∈[0,1] 上取值落入
     * 闭区间 [low,high] 的 t 区间，并与入参 current（另一坐标及 [0,1] 的可行区间）
     * 原地求交。
     *
     * <p>系数为整数，根用 double 求并加 {@link #EPS} 容差，使整数/半整数等精确相切
     * （擦边）稳定判为命中，而真实的微小未交（如 0.25 米间隙）保持不命中。</p>
     *
     * @return true 表示与 current 求交后仍非空
     */
    private static boolean intervalForQuadratic(int a, int b, int c, int low, int high,
                                                double[] current) {
        // q(t) = A t^2 - 2B t + a，其中 A=a-2b+c，B=a-b；B(0)=a，B(1)=c
        int bigA = a - 2 * b + c;
        int bigB = a - b;

        double lo = 1.0d;
        double hi = 0.0d;
        // 逐步并入满足约束的区间，初始为空集 [1,0]
        if (bigA == 0) {
            // q(t) 退化为线性：a - 2B t
            if (bigB == 0) {
                if (a >= low && a <= high) {
                    lo = 0.0d;
                    hi = 1.0d;
                }
            } else {
                double tLow = (a - high) / (2.0d * bigB);
                double tHigh = (a - low) / (2.0d * bigB);
                if (bigB < 0) {
                    double tmp = tLow;
                    tLow = tHigh;
                    tHigh = tmp;
                }
                double[] clipped = clip01(tLow, tHigh);
                if (clipped != null) {
                    lo = clipped[0];
                    hi = clipped[1];
                }
            }
        } else {
            // 开口方向决定可行域：A>0 时 q<=bound 在两根之间；A<0 时 q<=bound 在两根之外
            double[] between = clip01(
                    rootForValue(bigA, bigB, a, low, true),
                    rootForValue(bigA, bigB, a, high, false));
            if (bigA > 0) {
                if (between != null) {
                    lo = between[0];
                    hi = between[1];
                }
            } else {
                // 开口向下：并集 [0,rLow] ∪ [rHigh,1]，返回与 current 可能相交的部分
                double rLow = rootForValue(bigA, bigB, a, low, true);
                double rHigh = rootForValue(bigA, bigB, a, high, false);
                double left = Math.min(1.0d, rHigh + EPS);
                double right = Math.max(0.0d, rLow - EPS);
                boolean leftHits = current[0] <= left && current[1] >= 0.0d - EPS;
                boolean rightHits = current[1] >= right && current[0] <= 1.0d + EPS;
                if (leftHits) {
                    lo = 0.0d;
                    hi = left;
                }
                if (rightHits) {
                    if (lo > hi) {
                        lo = right;
                    }
                    hi = 1.0d;
                }
            }
        }

        if (lo > hi) {
            return false;
        }
        current[0] = Math.max(current[0], lo - EPS);
        current[1] = Math.min(current[1], hi + EPS);
        return current[0] <= current[1];
    }

    /** 求 q(t)=A t^2-2B t+a 取值等于 bound 时较小（small=true）或较大的实根；无实根返回越界值。 */
    private static double rootForValue(int bigA, int bigB, int a, int bound, boolean small) {
        // A t^2 - 2B t + (a-bound) = 0
        int cc = a - bound;
        long disc = (long) bigB * bigB - (long) bigA * cc;
        if (disc < 0L) {
            // 整系数判别式为负：无实根，用 NaN 交由调用方向外扩展为空/全集
            return small ? Double.NaN : Double.NaN;
        }
        double sqrt = Math.sqrt(disc);
        if (small) {
            return (bigB - sqrt) / bigA;
        }
        return (bigB + sqrt) / bigA;
    }

    /** 将区间裁剪到 [0,1]（含容差）；裁剪后为空或非法返回 null。 */
    private static double[] clip01(double low, double high) {
        if (Double.isNaN(low) || Double.isNaN(high)) {
            return null;
        }
        double lo = Math.max(0.0d, low - EPS);
        double hi = Math.min(1.0d, high + EPS);
        return lo <= hi ? new double[]{lo, hi} : null;
    }

    /** t 参数与整数边界比较的容差：覆盖 double 求根误差，远小于 1 米级的真实未交间隙。 */
    private static final double EPS = 1.0e-9;
}

