        return new CurveSegmentDto(cp(x0, y0), cp(x1, y1), cp(x2, y2));
    }

    /** 题干合成曲线 P0=(0,0), P1=(5,10), P2=(10,0)。 */
    private static List<CurveSegmentDto> arch() {
        return List.of(seg(0, 0, 5, 10, 10, 0));
    }

