        assertEquals("QUADRATIC", bDto.kind());
        assertTrue(bDto.pointsSnapshot().isEmpty());
        assertEquals(arch(), bDto.segmentsSnapshot(), "审核必须冻结完整 P0/P1/P2 控制点");

