        ApiException changedOperator = assertThrows(ApiException.class, () ->
                service.createCurveRoute(new CurveRouteCreateRequest("c6", arch(), "op2", requestId)));
        assertEquals(HttpStatus.CONFLICT, changedOperator.status());

